// Banque effective par langue : questions historiques + nouvelles questions
// visuelles (data_visual.js) moins les questions simples qu'elles remplacent,
// pour que chaque examen reste à exactement 180 questions.
const _bankCache = {};
function getQuestionBank(lang) {
  const key = (lang === 'en' || lang === 'ar') ? lang : 'fr';
  if (_bankCache[key]) return _bankCache[key];
  const base = key === 'en' ? QUESTIONS_EN : key === 'ar' ? QUESTIONS_AR : QUESTIONS_FR;
  let bank = base;
  if (typeof VISUAL_HIDDEN_IDS !== 'undefined') {
    const hidden = new Set(VISUAL_HIDDEN_IDS[key]);
    const extra = key === 'en' ? VISUAL_QUESTIONS_EN : key === 'ar' ? VISUAL_QUESTIONS_AR : VISUAL_QUESTIONS_FR;
    bank = base.filter(q => !hidden.has(q.id)).concat(extra);
  }
  _bankCache[key] = bank;
  return bank;
}
